/** Every file a kind collects, loaded once at startup. */
export const entryModules = import.meta.glob<Record<string, unknown>>(
	[
		"../**/*.actions.ts",
		"../**/*.blocks.ts",
		"../**/*.conditions.ts",
		"../**/*.lenses.ts",
		"../**/*.settings.ts",
		"../**/*.surface.ts",
	],
	{ eager: true },
);
